const FIGS: Record<string, Array<{ after: string; caption: string; src: string }>> = {}

const PR = 'Файл практикума — «praktikum-ishodnyj.xlsx», листы «Справочник» (коды и организации), «Платежи» (шесть платежей), «Сотрудники» (десять записей). Данные вымышленные.'
const VER = 'Версия Excel не подтверждена: у каждой функции ниже указано, с какой версии она есть, и чем заменить в Excel 2007–2019. Если формула даёт #ИМЯ?, вашей версии она неизвестна — используйте замену.'

// Строка-шаблон абзаца «Проверка себя»
const SRC = (list: string) => `Источники: ${list}; проверено 27.11.2026. Значения в примерах пересчитаны программно (Python), в самом Excel не проверялись.`

// ─────────────────────────────── 01. Ф12 ───────────────────────────────
